import {ITEMS,equipmentClass} from './inventory.js';
export function validateExtensions(s,require,finite,vector,actor,projectile){
 const state=s.chapter.ritual;if(state!==undefined){require(state&&Array.isArray(state.runes)&&state.runes.length<=3&&state.runes.every(r=>['Луна','Кость','Пламя'].includes(r))&&typeof state.unlocked==='boolean'&&typeof state.looted==='boolean');for(const k of ['hp','mana','strength'])require(finite(state.buffs?.[k],0,k==='strength'?90:10))}
 for(const [i,item] of s.chapter.slots.entries())if(item&&(i<6||i>=18))require(!equipmentClass(item.id)||equipmentClass(item.id)===s.chapter.p.classId);
 require(s.player.vitals.curseMultiplier===undefined||finite(s.player.vitals.curseMultiplier,.000001,1));
 const r=s.ritual;if(r!==undefined){require(r&&[null,'hut','trial'].includes(r.mode)&&finite(r.time,0)&&finite(r.playerSlow,0,7)&&finite(r.playerStun,0,3));if(r.origin)require(vector(r.origin.position)&&finite(r.origin.yaw)&&finite(r.origin.pitch,-1.35,1.35)&&[null,'hut'].includes(r.origin.mode));if(r.params){require(['sword','bow','mage'].includes(r.params.classId));for(const k of ['hp','mana','stamina','damage','cooldown','speed','physicalIncoming','magicIncoming','manaRegen','staminaRegen','skillCost','skillCooldown','level','rank'])require(finite(r.params[k],0,1000000))}if(r.mirror){actor(r.mirror.actor);require(r.params&&r.mirror.actor.id==='dark-self'&&finite(r.mirror.actor.hp,0,r.mirror.actor.maxHp));for(const k of ['stamina','mana','skillReady','cooldown','windup','blockLeft','blockReady'])require(finite(r.mirror[k],0));require(typeof r.mirror.skillPending==='boolean'&&typeof r.mirror.blockBroken==='boolean')}require(Array.isArray(r.shots)&&r.shots.length<=100);r.shots.forEach(b=>{projectile(b);require(typeof b.arrow==='boolean'&&typeof b.ice==='boolean'&&typeof b.straight==='boolean'&&finite(b.delay,0,1))});if(r.mode==='trial')require(r.mirror&&r.params&&r.origin)}
 const d=s.dungeon;if(d!==undefined){require(d&&[null,'dungeon','lich'].includes(d.mode)&&typeof d.bossDead==='boolean'&&typeof d.resetAfterBoss==='boolean'&&typeof d.curseFinished==='boolean');for(const k of ['time','fightTime','curseStep','summonReady','armorReady','armorLeft'])require(finite(d[k],0));if(d.teleportReady!==undefined)require(finite(d.teleportReady,0,20));if(d.boss){actor(d.boss);require(d.boss.id==='lich'&&d.boss.maxHp===570&&finite(d.boss.hp,0,570))}require(Array.isArray(d.mobs)&&d.mobs.length<=200);const ids=new Set();d.mobs.forEach(n=>{actor(n.actor);require(!ids.has(n.actor.id));ids.add(n.actor.id);require(['sword','bow','mage'].includes(n.kind)&&['dungeon','lich'].includes(n.zone)&&finite(n.actor.hp,0,n.actor.maxHp));for(const k of ['rise','stamina','blockReady','blockLeft'])require(finite(n[k],0));require(typeof n.broken==='boolean')});require(Array.isArray(d.chests)&&[0,2].includes(d.chests.length));d.chests.forEach(c=>{require(typeof c.opened==='boolean');if(c.contents!=null){require(Array.isArray(c.contents)&&c.contents.length<=3);c.contents.forEach(i=>require(['gold','health_potion','mana_potion','strength_potion'].includes(i.id)&&Number.isInteger(i.count)&&i.count>0&&i.count<=(i.id==='gold'?20:1)))}if(c.loot)require(finite(c.loot.gold,8,20)&&['health_potion','mana_potion'].includes(c.loot.potion)&&typeof c.loot.strength==='boolean')});require(Array.isArray(d.shots)&&d.shots.length<=100);d.shots.forEach(b=>{projectile(b);require(typeof b.arrow==='boolean'&&typeof b.ice==='boolean')});if(d.mode==='lich')require(d.boss);if(d.mode)require(!r?.mode)}
}
